mapper.select:
SELECT v.AMT_LMT_USAGE AS "amtLmtUsage",
       v.MAX_AMT_LMT   AS "maxAmtLmt"
FROM CORP_LMT_PC_DTL v
JOIN COM_ST_SRVC_CCY_MTRX scm ON scm.ID = v.SRVC_CCY_MTRX_ID
JOIN COM_ST_SRVC_CCY scy      ON scy.ID = scm.SRVC_CCY_ID
WHERE v.CORP_ID = #{companyId}
  AND scy.SRVC_CD = #{srvcCd}
  AND v.CCY_CD = #{ccyCd}
FETCH FIRST 1 ROWS ONLY

SELECT l.AMT_LMT_USAGE AS "amtLmtUsage",
       l.MAX_AMT_LMT   AS "maxAmtLmt"
FROM CORP_USR_GRP_LMT l
JOIN COM_ST_SRVC_CCY_MTRX scm ON scm.ID = l.SRVC_CCY_MTRX_ID
JOIN COM_ST_SRVC_CCY scy      ON scy.ID = scm.SRVC_CCY_ID
WHERE l.CORP_USR_GRP_ID = #{groupId}
  AND scy.SRVC_CD = #{srvcCd}
  AND l.CCY_CD = #{ccyCd}
FETCH FIRST 1 ROWS ONLY

SELECT DEBIT_LMT
FROM CORP_ACCT
WHERE CORP_ID = #{companyId}
  AND ACCT_NO = #{accountNo}
FETCH FIRST 1 ROWS ONLY

SELECT MAKE_LMT
FROM AUTH_LMT_SCHEME
WHERE CORP_ID = #{companyId}
  AND APRV_LVL_CD = #{aprvLvlCd}
  AND LMT_CCY_CD = #{ccyCd}
FETCH FIRST 1 ROWS ONLY

SELECT ID
FROM CORP_APRV_MTRX_MSTR
WHERE CORP_ID = #{companyId}
  AND SPI_MNU_CD = #{menuCd}
  AND CCY_CD = #{ccyCd}
FETCH FIRST 1 ROWS ONLY

mapper.update:
UPDATE CORP_LMT_PC_DTL
SET AMT_LMT_USAGE = NVL(AMT_LMT_USAGE, 0) + #{amount}
WHERE ID = #{id}

UPDATE CORP_USR_GRP_LMT
SET AMT_LMT_USAGE = NVL(AMT_LMT_USAGE, 0) + #{amount}
WHERE ID = #{id}

mapper.select:
SELECT CORP_USR_GRP_ID
FROM CORP_USR
WHERE ID = #{corpUsrId}

SELECT HOST_CIF_ID
FROM CORP
WHERE ID = #{companyId}

SELECT VALUE
FROM TRX_REF_NO_SEQUENCE
WHERE SERVICE_CD = #{srvcCd}
  AND CORP_ID = #{corpId}
  AND ROWNUM = 1
FOR UPDATE

mapper.update:
UPDATE TRX_REF_NO_SEQUENCE
SET VALUE = #{value}
WHERE SERVICE_CD = #{srvcCd}
  AND CORP_ID = #{corpId}
